#Requires -Version 5.1
<#
.SYNOPSIS
    Self-contained Azure Virtual Desktop pre-deployment readiness validation.
.DESCRIPTION
    Selects English, Spanish, or Portuguese and executes the complete readiness
    engine embedded in this file. No external script, repository module, OneDrive,
    Documents module path, or fixed root-drive temp directory is required. Save-Module
    requires a filesystem destination, so missing modules are staged in a unique
    OS-managed temporary directory. The engine removes imported modules and deletes
    that directory; worker-process exit guarantees assembly cleanup from memory.
#>
[CmdletBinding(SupportsShouldProcess = $false)]
param(
    [ValidateSet('English', 'Spanish', 'Portuguese', 'en-US', 'es-VE', 'pt-BR')]
    [string]$Language,
    [string]$SubscriptionId,
    [string]$TenantId,
    [string]$TargetRegion,
    [string]$VmSku = 'Standard_D4s_v5',
    [ValidateRange(1, 10000)]
    [int]$PlannedSessionHosts = 10,
    [string]$DomainName,
    [ValidateSet('ADDS', 'EntraID', 'EntraIDKerberos', 'EntraDS', 'All')]
    [string]$IdentityModel = 'All',
    [switch]$SkipConnectivityTests,
    [switch]$SkipADValidation,
    [string]$ResourceGroupName,
    [string]$VNetName,
    [string]$SubnetName,
    [string]$StorageAccountName,
    [switch]$NonInteractive,
    [ValidateSet('ExistingContext', 'Interactive', 'DeviceCode', 'ServicePrincipalSecret', 'ServicePrincipalCertificate', 'ManagedIdentity')]
    [string]$AuthMethod = 'ExistingContext',
    [string]$ApplicationId,
    [string]$CertificateThumbprint,
    [System.Management.Automation.PSCredential]$ServicePrincipalCredential,
    [string]$ReportPath = $(if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }),
    [switch]$ExportReport,
    [switch]$CriticalOnly,
    [switch]$PassThru,
    [switch]$NoExport,
    [switch]$SkipModuleValidation
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

# Embedded source hashes: English=0E423A9673FD97AD66B8DA85C03AF2A5DD906E988E8B8E52EC024BB51603A374; Spanish=55835A875CDC9BFCA582B3C54B1F4B192A958C451B1B590188F5FD44BDD06090; Portuguese=52DDD76898E997DC20677FACEA7E9D00A7F7E21899D7496E8B1E19C418A96E92
$embeddedPayloads = @{
    English = ''
    Spanish = ''
    Portuguese = ''
}

function Expand-EmbeddedScript {
    param([Parameter(Mandatory = $true)][string]$Payload)
    $compressed = [Convert]::FromBase64String($Payload)
    $input = New-Object IO.MemoryStream(,$compressed)
    $gzip = New-Object IO.Compression.GZipStream($input, [IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
    try { $reader.ReadToEnd() } finally { $reader.Dispose(); $gzip.Dispose(); $input.Dispose() }
}

function Protect-LauncherFile {
    param([Parameter(Mandatory = $true)][string]$Path)
    try {
        $identity = [Security.Principal.WindowsIdentity]::GetCurrent().Name
        $security = New-Object Security.AccessControl.FileSecurity
        $security.SetAccessRuleProtection($true, $false)
        $security.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($identity, 'FullControl', 'Allow')))
        $security.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule('SYSTEM', 'FullControl', 'Allow')))
        Set-Acl -LiteralPath $Path -AclObject $security -ErrorAction Stop
    } catch {
        Write-Verbose "Could not restrict temporary file ACL: $($_.Exception.Message)"
    }
}

$workerMode = $env:AVD00_EMBEDDED_WORKER -eq '1'
if ($workerMode) {
    $parameterFile = $env:AVD00_PARAMETER_FILE
    $outputFile = $env:AVD00_OUTPUT_FILE
    $errorFile = $env:AVD00_ERROR_FILE
    $workerLanguage = $env:AVD00_WORKER_LANGUAGE
    try {
        if (-not $embeddedPayloads.ContainsKey($workerLanguage)) { throw "Unsupported worker language: $workerLanguage" }
        $parameters = Import-Clixml -LiteralPath $parameterFile -ErrorAction Stop
        $env:AVD_REPORT_SCRIPT_NAME = '00_AVD_Check_Deployment_Readiness_Launcher'
        $env:PSModulePath = (($env:PSModulePath -split [IO.Path]::PathSeparator) |
            Where-Object { $_ -and $_ -notmatch '(?i)OneDrive|Documents[\\/](WindowsPowerShell|PowerShell)[\\/]Modules' }) -join [IO.Path]::PathSeparator
        $source = Expand-EmbeddedScript -Payload $embeddedPayloads[$workerLanguage]
        $engine = [scriptblock]::Create($source)
        $global:LASTEXITCODE = 0
        $result = & $engine @parameters
        $workerExitCode = $global:LASTEXITCODE
        if ($null -ne $result) {
            $result | Export-Clixml -LiteralPath $outputFile -Depth 40 -Force
            Protect-LauncherFile -Path $outputFile
        }
        exit $workerExitCode
    } catch {
        $_ | Out-String | Set-Content -LiteralPath $errorFile -Encoding UTF8 -Force
        Protect-LauncherFile -Path $errorFile
        exit 2
    }
}

if (-not $Language) {
    if ($NonInteractive) {
        $Language = 'English'
    } else {
        do {
            Write-Host ''
            Write-Host 'Select language / Seleccione el idioma / Selecione o idioma' -ForegroundColor Cyan
            Write-Host '  1. English'
            Write-Host '  2. Español'
            Write-Host '  3. Português'
            $languageChoice = Read-Host 'Choice / Opción / Opção [1]'
            if ([string]::IsNullOrWhiteSpace($languageChoice)) { $languageChoice = '1' }
        } until ($languageChoice -in @('1', '2', '3'))
        $Language = @{'1' = 'English'; '2' = 'Spanish'; '3' = 'Portuguese'}[$languageChoice]
    }
}
$normalizedLanguage = if ($Language -in @('Spanish', 'es-VE')) { 'Spanish' } elseif ($Language -in @('Portuguese', 'pt-BR')) { 'Portuguese' } else { 'English' }

$forwardParameters = @{}
foreach ($parameterName in $PSBoundParameters.Keys) {
    if ($parameterName -ne 'Language') { $forwardParameters[$parameterName] = $PSBoundParameters[$parameterName] }
}
if (-not $forwardParameters.ContainsKey('ReportPath')) { $forwardParameters.ReportPath = $ReportPath }

$powerShellExe = (Get-Process -Id $PID -ErrorAction SilentlyContinue).Path
if ([string]::IsNullOrWhiteSpace($powerShellExe) -or -not (Test-Path -LiteralPath $powerShellExe -PathType Leaf)) {
    $powerShellExe = if ($PSVersionTable.PSEdition -eq 'Core') { 'pwsh.exe' } else { 'powershell.exe' }
}

$operationId = [guid]::NewGuid().ToString('N')
$parameterFile = Join-Path ([IO.Path]::GetTempPath()) "AVD00_Parameters_$operationId.clixml"
$outputFile = Join-Path ([IO.Path]::GetTempPath()) "AVD00_Output_$operationId.clixml"
$errorFile = Join-Path ([IO.Path]::GetTempPath()) "AVD00_Error_$operationId.txt"
$moduleTempPath = Join-Path ([IO.Path]::GetTempPath()) "AVD_TempMod_$operationId"
$previousEnvironment = @{
    Worker = $env:AVD00_EMBEDDED_WORKER
    Parameters = $env:AVD00_PARAMETER_FILE
    Output = $env:AVD00_OUTPUT_FILE
    Error = $env:AVD00_ERROR_FILE
    Language = $env:AVD00_WORKER_LANGUAGE
    ModuleTemp = $env:AVD00_MODULE_TEMP_PATH
}
try {
    $forwardParameters | Export-Clixml -LiteralPath $parameterFile -Depth 20 -Force
    Protect-LauncherFile -Path $parameterFile
    $env:AVD00_EMBEDDED_WORKER = '1'
    $env:AVD00_PARAMETER_FILE = $parameterFile
    $env:AVD00_OUTPUT_FILE = $outputFile
    $env:AVD00_ERROR_FILE = $errorFile
    $env:AVD00_WORKER_LANGUAGE = $normalizedLanguage
    $env:AVD00_MODULE_TEMP_PATH = $moduleTempPath
    $child = Start-Process -FilePath $powerShellExe -ArgumentList @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $PSCommandPath) -Wait -PassThru -NoNewWindow
    $global:LASTEXITCODE = $child.ExitCode
    if (Test-Path -LiteralPath $outputFile -PathType Leaf) { Import-Clixml -LiteralPath $outputFile }
    if (Test-Path -LiteralPath $errorFile -PathType Leaf) {
        $detail = Get-Content -LiteralPath $errorFile -Raw
        throw $detail.Trim()
    }
} finally {
    foreach ($path in @($parameterFile, $outputFile, $errorFile)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$path)) {
            Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
        }
    }
    if (Test-Path -LiteralPath $moduleTempPath) {
        Remove-Item -LiteralPath $moduleTempPath -Recurse -Force -ErrorAction SilentlyContinue
    }
    $environmentMap = @{AVD00_EMBEDDED_WORKER='Worker';AVD00_PARAMETER_FILE='Parameters';AVD00_OUTPUT_FILE='Output';AVD00_ERROR_FILE='Error';AVD00_WORKER_LANGUAGE='Language';AVD00_MODULE_TEMP_PATH='ModuleTemp'}
    foreach ($name in $environmentMap.Keys) {
        $value = $previousEnvironment[$environmentMap[$name]]
        if ($null -eq $value) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue } else { Set-Item "Env:$name" $value }
    }
}